@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap');

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    font-family: 'Inter', sans-serif;
}

body {
    background: #0c0634;
    color: white;
}

.container {
    width: 90%;
    max-width: 1400px;
    margin: auto;
}

header {
    position: fixed;
    width: 100%;
    z-index: 100;
    padding: 25px 0;
    background-color: #0c0634;
}

.navbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo {
    display: flex;
    align-items: center;
    gap: 12px;
}

.logo img {
    width: 200px;
}

.logo h2 {
    font-size: 22px;
}

.logo span {
    font-size: 10px;
    color: #aaa;
}

nav ul {
    display: flex;
    gap: 30px;
    list-style: none;
}

nav a {
    color: white;
    text-decoration: none;
    font-size: 15px;
    transition: .3s;
}

nav a:hover,
nav a.active {
    color: #cc2326;
}

.quote-btn {
    text-decoration: none;
    background: linear-gradient(90deg,#f2292d,#cc2326);
    color: white;
    padding: 14px 28px;
    border-radius: 10px;
    font-weight: 600;
}

.hero {
    min-height: 100vh;
    background:
        radial-gradient(circle at top right,
            rgba(99,102,241,0.3),
            transparent 50%),
        linear-gradient(135deg,#090426,#15053f);
    overflow: hidden;
}

.hero-content {
    display: flex;
    align-items: center;
    justify-content: space-between;
    min-height: 100vh;
    gap: 80px;
}

.hero-text {
    max-width: 600px;
}

.tag {
    display: inline-block;
    padding: 10px 20px;
    border: 1px solid rgba(255,255,255,0.15);
    border-radius: 30px;
    margin-bottom: 30px;
    font-size: 14px;
    color: #ff6b35;
    background: rgba(255,255,255,0.05);
}

.hero h1 {
    font-size: 45px;
    line-height: 1.2;
    margin-bottom: 25px;
}

.hero h1 span {
    color: #cc2326;
}

.hero p {
    color: #c8c8c8;
    line-height: 1.8;
    font-size: 18px;
    margin-bottom: 40px;
}

.hero-buttons {
    display: flex;
    gap: 20px;
}

.primary-btn {
    background: linear-gradient(90deg,#f2292d,#cc2326);
    padding: 18px 32px;
    border-radius: 12px;
    color: white;
    text-decoration: none;
    font-weight: 600;
}

.secondary-btn {
    border: 1px solid rgba(255,255,255,0.2);
    padding: 18px 32px;
    border-radius: 12px;
    color: white;
    text-decoration: none;
}

.secondary-btn i {
    margin-left: 10px;
}

.hero-image {
    position: relative;
}

.hero-slider {
    position: relative;
    width: 100%;
    height: 90vh;
    overflow: hidden;
}

.slide {
    position: absolute;
    inset: 0;
    opacity: 0;
    visibility: hidden;
    transition: 0.8s;
}

.slide.active {
    opacity: 1;
    visibility: visible;
}

.slide img {
    width: 100%;
    height: 90vh;
    object-fit: cover;
}

.content {
    position: absolute;
    top: 50%;
    left: 8%;
    transform: translateY(-50%);
    color: white;
    max-width: 600px;
}

.content h1 {
    font-size: 60px;
    margin-bottom: 20px;
}

.content p {
    font-size: 20px;
    margin-bottom: 30px;
}

.btn {
    display: inline-block;
    background: #f2292d;
    color: white;
    padding: 15px 35px;
    border-radius: 8px;
    text-decoration: none;
}

.slider-btn {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    width: 50px;
    height: 50px;
    border: none;
    border-radius: 50%;
    background: rgba(255,255,255,0.2);
    backdrop-filter: blur(10px);
    color: white;
    cursor: pointer;
    z-index: 100;
}

.prev {
    left: 20px;
}

.next {
    right: 20px;
}

.dots {
    position: absolute;
    bottom: 25px;
    left: 50%;
    transform: translateX(-50%);
    display: flex;
    gap: 10px;
    z-index: 100;
}

.dot {
    width: 12px;
    height: 12px;
    background: rgba(255,255,255,0.5);
    border-radius: 50%;
    cursor: pointer;
}

.dot.active {
    background: white;
}

.partners-section {
    padding: 40px 0;
    background: #f8f9ff;
    overflow: hidden;
}

.partners-container {
    width: 90%;
    max-width: 1400px;
    margin: auto;
}

.section-title {
    text-align: center;
    font-size: 28px;
    color: #1d1d1d;
    margin-bottom: 10px;
    font-weight: 700;
}

.partners-slider {
    overflow: hidden;
    position: relative;
}

.partners-track {
    display: flex;
    align-items: center;
    width: max-content;
    animation: scrollBrands 30s linear infinite;
}

.partners-track img {
    width: 120px;
    height: 60px;
    object-fit: contain;
    transition: 0.3s;
}

.partners-track img:hover {
    transform: scale(1.1);
}

@keyframes scrollBrands {

    from {
        transform: translateX(0);
    }

    to {
        transform: translateX(-50%);
    }

}

.services-section {
    padding: 100px 0;
    background: #f8f9ff;
}

.container {
    width: 90%;
    max-width: 1400px;
    margin: auto;
}

.section-heading {
    text-align: center;
    margin-bottom: 60px;
}

.section-heading span {
    color: #6c63ff;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 2px;
}

.section-heading h2 {
    font-size: 42px;
    margin: 15px 0;
    color: #222;
}

.section-heading p {
    max-width: 700px;
    margin: auto;
    color: #666;
    line-height: 1.8;
}

.service-category {
    margin-bottom: 80px;
}

.service-category h3 {
    font-size: 30px;
    margin-bottom: 30px;
    color: #222;
    text-align: center;
}

.services-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 30px;
}

.service-card {
    background: #fff;
    padding: 30px;
    border-radius: 20px;
    text-align: center;
    box-shadow: 0 10px 30px rgba(0,0,0,0.05);
    transition: 0.3s;
}

.service-card:hover {
    transform: translateY(-10px);
}

.service-card img {
    width: 180px;
    height: 120px;
    object-fit: contain;
    margin-bottom: 20px;
}

.service-card h4 {
    margin-bottom: 15px;
    color: #222;
}

.service-card p {
    color: #666;
    line-height: 1.7;
    margin-bottom: 20px;
}

.service-card a {
    text-decoration: none;
    color: #6c63ff;
    font-weight: 600;
}

/*==============================
 WHY CHOOSE US
===============================*/

.why-choose-section{
    position: relative;
    padding:100px 0;
    background:linear-gradient(180deg,#f8fbff,#eef4ff);
    overflow:hidden;
}

.why-choose-section::before{
    content:"";
    position:absolute;
    width:350px;
    height:350px;
    background:#7c5cff20;
    border-radius:50%;
    top:-120px;
    left:-120px;
    filter:blur(40px);
}

.why-choose-section::after{
    content:"";
    position:absolute;
    width:280px;
    height:280px;
    background:#00d4ff15;
    border-radius:50%;
    bottom:-80px;
    right:-80px;
    filter:blur(50px);
}

.section-heading{
    max-width:760px;
    margin:0 auto 70px;
    text-align:center;
}

.section-heading span{
    display:inline-block;
    padding:8px 18px;
    border-radius:30px;
    background:#eef2ff;
    color:#6c63ff;
    font-size:13px;
    font-weight:700;
    letter-spacing:2px;
    text-transform:uppercase;
}

.section-heading h2{
    font-size:42px;
    line-height:1.2;
    margin:18px 0;
    color:#202124;
    font-weight:700;
}

.section-heading p{
    color:#666;
    line-height:1.8;
    font-size:17px;
}

.why-grid{
    display:grid;
    grid-template-columns:repeat(auto-fit,minmax(300px,1fr));
    gap:35px;
    align-items:stretch;
}

.why-card{
    position:relative;
    background:rgba(255,255,255,.75);
    backdrop-filter:blur(14px);
    border:1px solid rgba(108,99,255,.15);
    border-radius:22px;
    padding:45px 30px;
    text-align:center;
    overflow:hidden;
    transition:.45s ease;
    box-shadow:0 15px 40px rgba(0,0,0,.06);
}

.why-card::before{
    content:"";
    position:absolute;
    left:0;
    top:0;
    width:100%;
    height:5px;
    background:linear-gradient(90deg,#6c63ff,#0a1436);
    transform:scaleX(0);
    transform-origin:left;
    transition:.4s;
}

.why-card::after{
    content:"";
    position:absolute;
    top:-150%;
    left:-50%;
    width:60%;
    height:300%;
    background:rgba(255,255,255,.35);
    transform:rotate(25deg);
    transition:.6s;
}

.why-card:hover{
    transform:translateY(-12px);
    box-shadow:0 25px 50px rgba(108,99,255,.18);
}

.why-card:hover::before{
    transform:scaleX(1);
}

.why-card:hover::after{
    left:140%;
}

.why-card i{
    width:85px;
    height:85px;
    margin:auto auto 25px;
    display:flex;
    align-items:center;
    justify-content:center;
    border-radius:50%;
    font-size:34px;
    color:#fff;
    background:linear-gradient(135deg,#6c63ff,#0a1436);
    box-shadow:0 12px 25px rgba(108,99,255,.25);
    transition:.4s;
    animation:floatIcon 3s ease-in-out infinite;
}

.why-card:hover i{
    transform:rotateY(180deg) scale(1.08);
}

.why-card h3{
    font-size:24px;
    color:#222;
    margin-bottom:15px;
}

.why-card p{
    color:#666;
    line-height:1.8;
    font-size:15px;
}

@keyframes floatIcon{

    0%{
        transform:translateY(0);
    }

    50%{
        transform:translateY(-8px);
    }

    100%{
        transform:translateY(0);
    }

}

.why-card{
    opacity:0;
    transform:translateY(50px);
    animation:fadeUp .8s forwards;
}

.why-card:nth-child(2){
    animation-delay:.2s;
}

.why-card:nth-child(3){
    animation-delay:.4s;
}

@keyframes fadeUp{

    to{
        opacity:1;
        transform:translateY(0);
    }

}

/*==========================
 Industries Section
==========================*/

.benefit-section{
    position:relative;
    padding:100px 0;
    background:linear-gradient(135deg,#0d1b3e, #1f3c88,#0f172a);
    overflow:hidden;
}

.benefit-section::before{
    content:"";
    position:absolute;
    width:450px;
    height:450px;
    background:#6c63ff20;
    border-radius:50%;
    top:-180px;
    left:-120px;
    filter:blur(70px);
}

.benefit-section::after{
    content:"";
    position:absolute;
    width:350px;
    height:350px;
    background:#00d4ff15;
    border-radius:50%;
    bottom:-120px;
    right:-120px;
    filter:blur(70px);
}

.benefit-wrapper{
    position:relative;
    z-index:2;
    display:grid;
    grid-template-columns:1.2fr 1fr;
    gap:70px;
