    gap:25px;
    padding:28px;
    background:rgba(255,255,255,.06);
    border:1px solid rgba(255,255,255,.12);
    border-radius:18px;
    backdrop-filter:blur(12px);
    transition:.4s;
    position:relative;
    overflow:hidden;
}

.benefit-item::before{

    content:"";
    position:absolute;
    left:-80%;
    top:0;
    width:60%;
    height:100%;
    background:rgba(255,255,255,.15);
    transform:skewX(-25deg);
    transition:.7s;

}

.benefit-item:hover::before{

    left:150%;

}

.benefit-item:hover{

    transform:translateX(12px);
    border-color:#6c63ff;
    box-shadow:0 20px 40px rgba(0,0,0,.25);

}

.benefit-icon{

    width:75px;
    height:75px;
    border-radius:50%;
    background:linear-gradient(135deg,#0d1b3e, #1f3c88);
    display:flex;
    justify-content:center;
    align-items:center;
    flex-shrink:0;
    box-shadow:0 10px 30px rgba(108,99,255,.35);
}

.benefit-icon i{

    color:#fff;
    font-size:30px;
}


.benefit-content h3{

    color:#fff;
    margin-bottom:8px;
    font-size:22px;

}

.benefit-content p{

    color:#d4d8e4;
    line-height:1.7;

}

.benefit-right span{

    color:#7aa8ff;
    font-weight:700;
    text-transform:uppercase;
    letter-spacing:2px;
}

.benefit-right h2{

    color:#fff;
    font-size:42px;
    margin:20px 0;
    line-height:1.2;

}

.benefit-right p{

    color:#c8d1e2;
    line-height:1.9;
    margin-bottom:20px;
    font-size:16px;

}

.benefit-item{

    animation:floatBox 5s ease-in-out infinite;

}

.benefit-item:nth-child(2){

