        justify-content: center;
        margin-top: 15px;
    }
}

/* Animation for cards */
@keyframes floatIcon {
    0% {
        transform: translateY(0);
    }
    50% {
        transform: translateY(-6px);
    }
    100% {
        transform: translateY(0);
    }
}

.why-card i {
    animation: floatIcon 3s ease-in-out infinite;
}

@keyframes floatBox {
    0% {
        transform: translateY(0);
    }
    50% {
        transform: translateY(-6px);
    }
    100% {
        transform: translateY(0);
    }
}

.benefit-item {
    animation: floatBox 5s ease-in-out infinite;
}

.benefit-item:nth-child(2) {
    animation-delay: 0.5s;
}
.benefit-item:nth-child(3) {
    animation-delay: 1s;
}
.benefit-item:nth-child(4) {
    animation-delay: 1.5s;
}
.benefit-item:nth-child(5) {
    animation-delay: 2s;
}

@keyframes floatCTA {
    0% {
        transform: translateY(0);
    }
    50% {
        transform: translateY(-6px);
    }
    100% {
        transform: translateY(0);
    }
}

.cta-box {
    animation: floatCTA 5s ease-in-out infinite;
}

toolUseResult.content:
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap');

* {
    {
    {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    font-family: 'Inter', sans-serif;
}

body {
    background: #0c0634;
    color: white;
}

/* Container */
.container {
    width: 90%;
    max-width: 1400px;
    margin: auto;
}

/* Header */
header {
    position: fixed;
    width: 100%;
    z-index: 100;
    padding: 20px 0;
    background-color: #0c0634;
}

header .container {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo {
    display: flex;
    align-items: center;
    gap: 12px;
}

.logo img {
    width: 150px;
}

.logo h2 {
    font-size: 20px;
}

.logo span {
    font-size: 10px;
    color: #aaa;
}

nav ul {
    display: flex;
    gap: 20px;
    list-style: none;
}

nav a {
    color: white;
    text-decoration: none;
    font-size: 14px;
    transition: .3s;
}

nav a:hover,
nav a.active {
    color: #cc2326;
}

.quote-btn {
    text-decoration: none;
    background: linear-gradient(90deg,#f2292d,#cc2326);
    color: white;
    padding: 12px 24px;
    border-radius: 8px;
    font-weight: 600;
    font-size: 14px;
}

/* Hero Slider */
.hero-slider {
    position: relative;
    width: 100%;
    height: 100vh;
    overflow: hidden;
    margin-top: 60px; /* For fixed header */
}

.slide {
    position: absolute;
    inset: 0;
    opacity: 0;
    visibility: hidden;
    transition: 0.8s ease;
}

.slide.active {
    opacity: 1;
    visibility: visible;
}

.slide img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.content {
    position: absolute;
    top: 50%;
    left: 5%;
    transform: translateY(-50%);
    color: white;
    max-width: 500px;
    padding: 20px;
    background: rgba(0,0,0,0.4);
    border-radius: 10px;
}

.content h1 {
    font-size: 2.5rem;
    margin-bottom: 15px;
    line-height: 1.2;
}

.content h1 span {
    color: #cc2326;
}

.content p {
    font-size: 1.1rem;
    line-height: 1.6;
    margin-bottom: 20px;
    color: #c8c8c8;
}

.btn {
    display: inline-block;
    background: #f2292d;
    color: white;
    padding: 12px 25px;
    border-radius: 6px;
    text-decoration: none;
    font-weight: 600;
    transition: 0.3s;
}

.btn:hover {
    background: #e32628;
    transform: translateY(-2px);
}

.slider-btn {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    width: 45px;
    height: 45px;
    border: none;
    border-radius: 50%;
    background: rgba(255,255,255,0.2);
    backdrop-filter: blur(5px);
    color: white;
    cursor: pointer;
    z-index: 100;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 18px;
}

.prev {
    left: 15px;
}

.next {
    right: 15px;
}

.slider-btn:hover {
    background: rgba(255,255,255,0.3);
}

.dots {
    position: absolute;
    bottom: 20px;
    left: 50%;
    transform: translateX(-50%);
    display: flex;
    gap: 8px;
    z-index: 100;
}

.dot {
    width: 10px;
    height: 10px;
    background: rgba(255,255,255,0.5);
    border-radius: 50%;
    cursor: pointer;
    transition: 0.3s;
}

.dot.active {
    background: white;
    transform: scale(1.2);
}

/* Partners Section */
.partners-section {
    padding: 30px 0;
    background: #f8f9ff;
    overflow: hidden;
}

.partners-section .section-title {
    text-align: center;
    font-size: 24px;
    color: #1d1d1d;
    margin-bottom: 15px;
}

.partners-track {
    display: flex;
    align-items: center;
    width: max-content;
    animation: scrollBrands 25s linear infinite;
}

.partners-track img {
    width: 100px;
    height: 50px;
    object-fit: contain;
    margin: 0 10px;
    transition: 0.3s;
}

.partners-track img:hover {
    transform: scale(1.1);
}

@keyframes scrollBrands {
    from {
        transform: translateX(0);
    }
    to {
        transform: translateX(-50%);
    }
}

/* Services Section */
.services-section {
    padding: 80px 0;
    background: #f8f9ff;
}

.services-section .section-heading {
    text-align: center;
    margin-bottom: 40px;
}

.services-section .section-heading span {
