}

.service-category {
    margin-bottom: 60px;
}

.service-category h3 {
    font-size: 1.8rem;
    margin-bottom: 20px;
    color: #222;
    text-align: center;
}

.services-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 20px;
}

.service-card {
    background: #fff;
