}

.service-card a {
    text-decoration: none;
    color: #6c63ff;
    font-weight: 600;
    font-size: 0.9rem;
}

/* Why Choose Us Section */
.why-choose-section {
    position: relative;
    padding: 60px 0;
    background: linear-gradient(180deg,#f8fbff,#eef4ff);
    overflow: hidden;
}

.why-choose-section::before {
    content: "";
    position: absolute;
    width: 250px;
    height: 25-200px;
    background:#7c5cff20;
    border-radius:50%;
    top:-80px;
    left:-80px;
    filter:blur(30px);
}

.why-choose-section::after {
    content: "";
    position: absolute;
    width: 200px;
    height: 200px;
    background:#00d4ff15;
    border-radius:50%;
    bottom:-60px;
    right:-60px;
    filter:blur(40px);
}

.why-choose-section .section-heading {
    text-align: center;
    margin-bottom: 40px;
}

.why-choose-section .section-heading span {
    display: inline-block;
    padding: 6px 12px;
    border-radius: 25px;
    background:#eef2ff;
    color:#6c63ff;
    font-size:12px;
    font-weight:700;
    letter-spacing:1px;
    text-transform:uppercase;
}

.why-choose-section .section-heading h2 {
    font-size: ize: 2.4rem;
    line-height:1.2;
    margin:15px 0;
    color:#202124;
    font-weight:700;
}

.why-choose-section .section-heading p {
    color:#666;
    line-height:1.6;
    font-size:1rem;
    max-width: 700px;
    margin: 0 auto 20px;
}

.why-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 25px;
}

.why-card {
    position:relative;
    background:rgba(255,255,255,.75);
    backdrop-filter:blur(10px);
    border:1px solid rgba(108,99,255,.15);
    border-radius:18px;
    padding:30px 20px;
    text-align:center;
    overflow:hidden;
    transition:.3s ease;
    box-shadow:0 10px 25px rgba(0,0,0,.05);
}

.why-card::before{
    content:"";
    position:absolute;
    left:0;
    top:0;
    width:100%;
    height:3px;
    background:linear-gradient(90deg,#6c63ff,#0a1436);
    transform:scaleX(0);
    transform-origin:left;
    transition:.3s;
}

.why-card::after{
    content:"";
    position:absolute;
    top:-100%;
    left:-50%;
    width:50%;
    height:200%;
    background:rgba(255,255,255,.25);
    transform:rotate(15deg);
    transition:.4s;
}

.why-card:hover{
    transform:translateY(-5px);
    box-shadow:0 15px 30px rgba(108,99,255,.12);
}

.why-card:hover::before{
