    color:#fff;
    background:linear-gradient(135deg,#6c63ff,#0a1436);
    box-shadow:0 8px 15px rgba(108,99,255,.2);
    transition:.3s;
}

.why-card:hover i{
    transform:rotateY(180deg) scale(1.05);
}

.why-card h3{
    font-size:1.2rem;
    color:#222;
    margin-bottom:10px;
}

.why-card p{
    color:#666;
    line-height:1.5;
    font-size:0.9rem;
}

/* Industries We Serve Section */
.benefit-section{
    position:relative;
    padding:60px 0;
    background:linear-gradient(135deg,#0d1b3e, #1f3c88,#0f172a);
    overflow:hidden;
}

.benefit-section::before{
    content:"";
    position:absolute;
    width:300px;
    height:300px;
    background:#6c63ff20;
    border-radius:50%;
    top:-120px;
    left:-60px;
    filter:blur(50px);
}

.benefit-section::after{
    content:"";
    position:absolute;
    width:250px;
    height:250px;
    background:#00d4ff15;
    border-radius:50%;
    bottom:-80px;
    right:-80px;
    filter:blur(50px);
}

.benefit-wrapper{
    position:relative;
