}

.cta-box{
    position:relative;
    max-width:900px;
    margin:auto;
    text-align:center;
    padding:50px 30px;
    border-radius:20px;
    background:linear-gradient(135deg,#ffffff,#f5f9ff);
    border:1px solid #e5ecff;
    box-shadow:0 15px 30px rgba(0,0,0,.05);
}

.cta-box::before{
    content:"";
    position:absolute;
