}

.primary-btn:hover{
    transform:translateY(-3px);
    box-shadow:0 10px 20px rgba(108,99,255,.3);
}

.secondary-btn{
    display:inline-flex;
    align-items:center;
    justify-content:center;
    padding:12px 25px;
    border:2px solid #6c63ff;
    color:#6c63ff;
    text-decoration:none;
    border-radius:25px;
    font-weight:600;
    transition:.3s;
}

.secondary-btn:hover{
    background:#6c63ff;
    color:#fff;
    transform:translateY(-3px);
}

/* Footer */
.footer {
    background: #0d1326;
    color: #fff;
    padding: 50px 0 20px;
