    box-shadow:0 15px 30px rgba(108,99,255,.12);
}

.why-card:hover::before{
    transform:scaleX(1);
}

.why-card:hover::after{
    left:120%;
}

.why-card i{
    width:60px;
    height:60px;
    margin:0 auto 15px;
    display:flex;
    align-items:center;
    justify-content:center;
    border-radius:50%;
    font-size:24px;
    color:#fff;
    background:linear-gradient(135deg,#6c63ff,#0a1436);
    box-shadow:0 8px 15px rgba(108,99,255,.2);
    transition:.3s;
}

.why-card:hover i{
    transform:rotateY(180deg) scale(1.05);
}

.why-card h3{
    font-size:1.2rem;
    color:#222;
    margin-bottom:10px;
}

.why-card p{
    color:#666;
    line-height:1.5;
    font-size:0.9rem;
}

/* Industries We Serve Section */
.benefit-section{
    position:relative;
    padding:60px 0;
    background:linear-gradient(135deg,#0d1b3e, #1f3c88,#0f172a);
    overflow:hidden;
}

.benefit-section::before{
    content:"";
    position:absolute;
    width:300px;
    height:300px;
    background:#6c63ff20;
    border-radius:50%;
    top:-120px;
    left:-60px;
    filter:blur(50px);
}

.benefit-section::after{
    content:"";
    position:absolute;
    width:250px;
    height:250px;
    background:#00d4ff15;
    border-radius:50%;
    bottom:-80px;
    right:-80px;
    filter:blur(50px);
}

.benefit-wrapper{
    position:relative;
    display:grid;
    grid-template-columns:1fr 1fr;
    gap:40px;
    align-items:center;
}

.benefit-left{
    display:flex;
    flex-direction:column;
    gap:20px;
}

.benefit-item{
    display:flex;
    align-items:center;
    gap:20px;
    padding:22px;
    background:rgba(255,255,255,.06);
    border:1px solid rgba(255,255,255,.1);
    border-radius:14px;
    backdrop-filter:blur(8px);
    transition:.3s;
}

.benefit-item:hover{
    transform:translateX(8px);
    border-color:#6c63ff;
    box-shadow:0 12px 20px rgba(0,0,0,.15);
}

.benefit-icon{
    width:60px;
    height:60px;
    border-radius:50%;
    background:linear-gradient(135deg,#0d1b3e, #1f3c88);
    display:flex;
    justify-content:center;
    align-items:center;
    flex-shrink:0;
    box-shadow:0 6px 12px rgba(108,99,255,.25);
}

.benefit-icon i{
    color:#fff;
    font-size:22px;
}

.benefit-content h3{
    color:#fff;
    margin-bottom:6px;
    font-size:1.1rem;
}

.benefit-content p{
    color:#d4d8e4;
    line-height:1.5;
    font-size:0.9rem;
}

.benefit-right{
    display:flex;
    flex-direction:column;
    gap:15px;
}

.benefit-right span{
    color:#7aa8ff;
    font-weight:700;
    text-transform:uppercase;
    letter-spacing:1px;
    font-size:0.9rem;
}

.benefit-right h2{
    color:#fff;
    font-size:1.8rem;
    margin:0;
    line-height:1.2;
}

.benefit-right p{
    color:#c8d1e2;
    line-height:1.6;
    font-size:0.9rem;
}

/* CTA Section */
.cta-section{
    padding:50px 20px;
    background:#f7f9fc;
}

.cta-box{
    position:relative;
    max-width:900px;
    margin:auto;
    text-align:center;
    padding:50px 30px;
    border-radius:20px;
    background:linear-gradient(135deg,#ffffff,#f5f9ff);
    border:1px solid #e5ecff;
    box-shadow:0 15px 30px rgba(0,0,0,.05);
}

.cta-box::before{
    content:"";
    position:absolute;
    width:150px;
    height:150px;
    background:#6c63ff12;
    border-radius:50%;
    top:-60px;
    left:-40px;
}

.cta-box::after{
    content:"";
    position:absolute;
    width:120px;
    height:120px;
    background:#00c6ff10;
    border-radius:50%;
    bottom:-50px;
    right:-40px;
}

.cta-box>*{
    position:relative;
    z-index:2;
}

.cta-tag{
    display:inline-block;
    padding:6px 12px;
    border-radius:30px;
    background:#eef2ff;
    color:#6c63ff;
    font-size:12px;
    font-weight:700;
    letter-spacing:1px;
    text-transform:uppercase;
    margin-bottom:12px;
}

.cta-box h2{
    font-size:2rem;
    color:#1d2433;
    margin-bottom:15px;
    line-height:1.2;
}

.cta-box p{
    max-width:700px;
    margin:0 auto 25px;
    color:#6b7280;
    line-height:1.6;
    font-size:0.95rem;
}

.cta-buttons{
    display:flex;
    justify-content:center;
    gap:15px;
    flex-wrap:wrap;
}

.primary-btn{
    display:inline-flex;
    align-items:center;
    justify-content:center;
    padding:12px 25px;
    background:linear-gradient(135deg,#6c63ff,#4f46e5);
    color:#fff;
    text-decoration:none;
    border-radius:25px;
    font-weight:600;
    transition:.3s;
    box-shadow:0 6px 12px rgba(108,99,255,.2);
}

.primary-btn:hover{
    transform:translateY(-3px);
    box-shadow:0 10px 20px rgba(108,99,255,.3);
}

.secondary-btn{
    display:inline-flex;
    align-items:center;
    justify-content:center;
    padding:12px 25px;
    border:2px solid #6c63ff;
    color:#6c63ff;
    text-decoration:none;
    border-radius:25px;
    font-weight:600;
    transition:.3s;
}

.secondary-btn:hover{
    background:#6c63ff;
    color:#fff;
    transform:translateY(-3px);
}

/* Footer */
.footer {
    background: #0d1326;
    color: #fff;
    padding: 80px 0 20px;
}

.footer-grid {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr 1fr 1.5fr;
    gap: 40px;
}

.footer-column h4 {
    font-size: 20px;
    margin-bottom: 25px;
    position: relative;
}

.footer-column h4::after {
    content: "";
    width: 50px;
    height: 3px;
    background: #cc2326;
    position: absolute;
    left: 0;
    bottom: -10px;
}

.footer-logo {
    display: flex;
    align-items: center;
    gap: 15px;
    margin-bottom: 20px;
}

.footer-logo img {
    width: 50px;
}

.footer-column p {
    color: #cfcfcf;
    line-height: 1.8;
    margin-bottom: 25px;
}

.footer-column ul {
    list-style: none;
}

.footer-column ul li {
    margin-bottom: 14px;
}

.footer-column ul li a {
    color: #cfcfcf;
    text-decoration: none;
    transition: 0.3s;
}

.footer-column ul li a:hover {
    color: #cc2326;
    padding-left: 5px;
}

.contact-list li {
    display: flex;
    gap: 12px;
    align-items: flex-start;
    color: #cfcfcf;
}

.contact-list i {
    color: #cc2326;
    margin-top: 4px;
}

.social-links {
    display: flex;
    gap: 15px;
}

.social-links a {
    width: 42px;
    height: 42px;
    background: rgba(255,255,255,0.1);
    color: #fff;
    border-radius: 50%;
    display: flex;
    justify-content: center;
    align-items: center;
    text-decoration: none;
    transition: 0.3s;
}

.social-links a:hover {
    background: #cc2326;
    transform: translateY(-5px);
}

.footer-bottom {
    border-top: 1px solid rgba(255,255,255,0.1);
    margin-top: 60px;
    padding-top: 20px;
    text-align: center;
}

.footer-bottom p {
    color: #aaa;
    font-size: 14px;
}

/* Animations */
@keyframes floatIcon {
    0% {
        transform: translateY(0);
    }
    50% {
        transform: translateY(-6px);
    }
    100% {
        transform: translateY(0);
    }
}

.why-card i {
    animation: floatIcon 3s ease-in-out infinite;
}

@keyframes floatBox {
    0% {
        transform: translateY(0);
    }
    50% {
        transform: translateY(-6px);
    }
    100% {
        transform: translateY(0);
    }
}

.benefit-item {
    animation: floatBox 5s ease-in-out infinite;
}

.benefit-item:nth-child(2) {
    animation-delay: 0.5s;
}
.benefit-item:nth-child(3) {
    animation-delay: 1s;
}
.benefit-item:nth-child(4) {
    animation-delay: 1.5s;
}
.benefit-item:nth-child(5) {
    animation-delay: 2s;
}

@keyframes floatCTA {
    0% {
        transform: translateY(0);
    }
    50% {
        transform: translateY(-6px);
    }
    100% {
        transform: translateY(0);
    }
}

.cta-box {
    animation: floatCTA 5s ease-in-out infinite;
}

/* Responsive Adjustments */
@media (max-width: 768px) {
    .partners-track img {
        width: 80px;
        height: 40px;
    }

    .service-card img {
        width: 100px;
        height: 70px;
    }

    }

    .content h1 {
        font-size: 2rem;
    }

    .content p {
        font-size: 1rem;
    }

    .why-choose-section .section-heading h2 {
        font-size: 2rem;
    }

    .benefit-right h2 {
        font-size: 1.5rem;
    }

    .cta-box h2 {
        font-size: 1.75rem;
    }
}

@media (max-width: 480px) {
    .partners-track img {
        width: 60px;
        height: 30px;
    }

    .service-card img {
        width: 80px;
        height: 50px;
    }

    .content {
        left: 5%;
        padding: 15px;
    }

    .content h1 {
        font-size: 1.5rem;
    }

    .content p {
        font-size: 0.9rem;
    }

    .btn {
        padding: 10px 20px;
        font-size: 0.9rem;
    }

    .logo img {
        width: 120px;
    }

    .logo h2 {
        font-size: 18px;
    }

    nav ul {
        gap: 10px;
    }

    nav a {
        font-size: 12px;
    }

    .quote-btn {
        padding: 10px 18px;
        font-size: 12px;
    }

    .why-choose-section .section-heading h2 {
        font-size: 1.75rem;
    }

    .benefit-right h2 {
        font-size: 1.25rem;
    }

    .cta-box h2 {
        font-size: 1.5rem;
    }

    .footer-grid {
        grid-template-columns: 1fr;
        text-align: center;
        gap: 20px;
    }

    .footer-column h4::after {
        left: 50%;
        transform: translateX(-50%);
    }

    .footer-logo {
        justify-content: center;
    }

    .contact-list {
        flex-direction: column;
        align-items: center;
    }

    .social-links {
        justify-content: center;
        margin-top: 15px;
    }
}

